CREATE TABLE clinic_resource(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),campus_id BIGINT NOT NULL REFERENCES campus(id),kind VARCHAR(20) NOT NULL,name VARCHAR(80) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(tenant_id,campus_id,kind,name));
CREATE TABLE schedule_resource(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),resource_id BIGINT NOT NULL REFERENCES clinic_resource(id),schedule_id BIGINT NOT NULL REFERENCES clinic_schedule(id),start_at TIMESTAMP NOT NULL,end_at TIMESTAMP NOT NULL,status VARCHAR(20) NOT NULL,UNIQUE(schedule_id,resource_id));
CREATE INDEX idx_resource_overlap ON schedule_resource(tenant_id,resource_id,status,start_at,end_at);
